    // value used in measurement timing budget calculations
    // assumes PresetMode is LOWPOWER_AUTONOMOUS
    //
    // vhv = LOWPOWER_AUTO_VHV_LOOP_DURATION_US + LOWPOWERAUTO_VHV_LOOP_BOUND
    //       (tuning parm default) * LOWPOWER_AUTO_VHV_LOOP_DURATION_US
    //     = 245 + 3 * 245 = 980
    // TimingGuard = LOWPOWER_AUTO_OVERHEAD_BEFORE_A_RANGING +
    //               LOWPOWER_AUTO_OVERHEAD_BETWEEN_A_B_RANGING + vhv
    //             = 1448 + 2100 + 980 = 4528
    static const uint32_t TimingGuard = 4528;

    // value in DSS_CONFIG__TARGET_TOTAL_RATE_MCPS register,
    // used in DSS calculations
    static const uint16_t TargetRate = 0x0A00;

    uint16_t fast_osc_frequency;
    uint16_t osc_calibrate_val;
    // uint32_t sum_mm;
    uint32_t counter;
    bool calibrated;

    typedef struct
    {
    uint32_t NumberOfZones;
    uint32_t MaxNumberOfTargetsPerZone;
    uint32_t CustomROI;          /*!< Not available: 0, Available: 1 */
    uint32_t ThresholdDetection; /*!< Not available: 0, Available: 1 */
    } RANGING_SENSOR_Capabilities_t;
    typedef struct
    {
    uint32_t RangingProfile;
    uint32_t TimingBudget;   /*!< Expressed in milliseconds */
    uint32_t Frequency;      /*!< Expressed in Hz */
    uint32_t EnableAmbient;  /*<! Enable: 1, Disable: 0 */
    uint32_t EnableSignal;   /*<! Enable: 1, Disable: 0 */
    } RANGING_SENSOR_ProfileConfig_t;
